// nxeon-shipper is a tiny, dependency-free telemetry agent installed on every
// Nxeon-provisioned VPS/game server via cloud-init (see worker/index.ts
// buildCloudInit()). It watches two local sources:
//
//  1. SSH auth events, via `journalctl -u ssh/sshd -f` (falls back to tailing
//     /var/log/auth.log on images that don't run journald-backed sshd logging).
//  2. A web server access log, if one happens to be running on the box
//     (nginx / apache2 / caddy — checked by path, first match wins). Most
//     bare VPS instances don't run one; that's fine, this part is skipped.
//
// Events are batched and shipped over HTTPS to the Nxeon ingestion endpoint,
// authenticated with a per-server bearer token minted at provision time
// (see lib/telemetry-token.ts). The agent is deliberately conservative about
// resources: everything is a handful of goroutines, log tailing is a cheap
// poll loop (no inotify dependency), and the outbound buffer is a small ring
// that drops the OLDEST events first under sustained backpressure rather than
// growing unbounded or blocking the tailers. If the ingest endpoint is down,
// the agent just keeps sampling and quietly drops what doesn't fit — it never
// blocks, panics, or spikes CPU retrying.
//
// Build: CGO_ENABLED=0 go build -ldflags="-s -w" -o nxeon-shipper .
// (static binary, no libc dependency, cross-compiles trivially with
// GOOS/GOARCH — see agent/nxeon-shipper/build.sh)
package main

import (
	"bufio"
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"io"
	"log"
	"net/http"
	"os"
	"os/exec"
	"path/filepath"
	"regexp"
	"strconv"
	"strings"
	"sync"
	"time"
)

// ---- Config -----------------------------------------------------------

const (
	configPath      = "/etc/nxeon/shipper.json"
	maxBufferedEvts = 2000 // ring cap; oldest dropped first under backpressure
	batchMaxEvents  = 50
	batchInterval   = 3 * time.Second
	httpTimeout     = 8 * time.Second
)

// Config is written once by cloud-init at provision time. NodeKind is one of
// VPS | GAME | HOSTING | MAIL (HOSTING/MAIL are used by the centralized
// per-node deployment, not the per-server cloud-init path, but the binary is
// identical either way — only the config differs).
type Config struct {
	ServerID  string `json:"server_id"`
	Token     string `json:"token"`
	IngestURL string `json:"ingest_url"`
	NodeKind  string `json:"node_kind"`
	Label     string `json:"label"` // hostname / display label for the admin UI
}

func loadConfig() (*Config, error) {
	b, err := os.ReadFile(configPath)
	if err != nil {
		return nil, fmt.Errorf("read %s: %w", configPath, err)
	}
	var c Config
	if err := json.Unmarshal(b, &c); err != nil {
		return nil, fmt.Errorf("parse %s: %w", configPath, err)
	}
	if c.ServerID == "" || c.Token == "" || c.IngestURL == "" {
		return nil, fmt.Errorf("%s missing server_id/token/ingest_url", configPath)
	}
	if c.NodeKind == "" {
		c.NodeKind = "VPS"
	}
	return &c, nil
}

// ---- Event shape (mirrors lib/telemetry.ts EventIn on the server) -----

type Event struct {
	Type   string `json:"type"`           // SSH_LOGIN | SSH_LOGOUT | SSH_FAILED | VISITOR | MAIL_AUTH
	TS     string `json:"ts"`             // RFC3339
	IP     string `json:"ip,omitempty"`
	User   string `json:"user,omitempty"` // ssh username, or "" for visitor events
	Path   string `json:"path,omitempty"` // request path for VISITOR events
	Status string `json:"status,omitempty"`
	Meta   string `json:"meta,omitempty"` // free-form extra (method, UA, port...)
	// Site distinguishes which vhost/customer a VISITOR event belongs to on a
	// centralized (HOSTING) node running one shipper for many customer sites.
	Site string `json:"site,omitempty"`
}

// ---- Ring buffer + batching sender --------------------------------------

type ring struct {
	mu   sync.Mutex
	buf  []Event
	cap  int
}

func newRing(cap int) *ring { return &ring{buf: make([]Event, 0, cap), cap: cap} }

func (r *ring) push(e Event) {
	r.mu.Lock()
	defer r.mu.Unlock()
	if len(r.buf) >= r.cap {
		// Drop the oldest quarter to make room, rather than dropping one at a
		// time under sustained pressure (cheaper than a per-event shift).
		drop := r.cap / 4
		if drop < 1 {
			drop = 1
		}
		r.buf = append(r.buf[:0], r.buf[drop:]...)
	}
	r.buf = append(r.buf, e)
}

// drain removes up to n events (oldest first) and returns them.
func (r *ring) drain(n int) []Event {
	r.mu.Lock()
	defer r.mu.Unlock()
	if n > len(r.buf) {
		n = len(r.buf)
	}
	if n == 0 {
		return nil
	}
	out := make([]Event, n)
	copy(out, r.buf[:n])
	r.buf = append(r.buf[:0], r.buf[n:]...)
	return out
}

type batchPayload struct {
	ServerID string  `json:"server_id"`
	NodeKind string  `json:"node_kind"`
	Label    string  `json:"label"`
	Events   []Event `json:"events"`
}

func sender(ctx context.Context, cfg *Config, r *ring) {
	client := &http.Client{Timeout: httpTimeout}
	backoff := time.Second
	const maxBackoff = 30 * time.Second
	ticker := time.NewTicker(batchInterval)
	defer ticker.Stop()
	for {
		select {
		case <-ctx.Done():
			return
		case <-ticker.C:
		}
		evts := r.drain(batchMaxEvents)
		if len(evts) == 0 {
			continue
		}
		payload := batchPayload{ServerID: cfg.ServerID, NodeKind: cfg.NodeKind, Label: cfg.Label, Events: evts}
		body, err := json.Marshal(payload)
		if err != nil {
			continue
		}
		req, err := http.NewRequestWithContext(ctx, http.MethodPost, cfg.IngestURL, bytes.NewReader(body))
		if err != nil {
			continue
		}
		req.Header.Set("Content-Type", "application/json")
		req.Header.Set("Authorization", "Bearer "+cfg.Token)
		resp, err := client.Do(req)
		if err != nil || resp.StatusCode >= 300 {
			if resp != nil {
				resp.Body.Close()
			}
			// Endpoint unreachable / rejecting: DON'T requeue (that's how a
			// slow backend turns into unbounded memory growth on the guest);
			// the events are simply lost, matching the "buffer briefly and
			// drop old events" resilience requirement. Back off so a downed
			// ingest endpoint doesn't turn into a retry storm across every
			// customer VM at once.
			if backoff < maxBackoff {
				backoff *= 2
				if backoff > maxBackoff {
					backoff = maxBackoff
				}
			}
			select {
			case <-ctx.Done():
				return
			case <-time.After(backoff):
			}
			continue
		}
		resp.Body.Close()
		backoff = time.Second
	}
}

// ---- SSH auth tailing ----------------------------------------------------

var (
	reAccepted   = regexp.MustCompile(`Accepted (\S+) for (\S+) from (\S+) port (\d+)`)
	reFailed     = regexp.MustCompile(`Failed (\S+) for (?:invalid user )?(\S+) from (\S+) port (\d+)`)
	reDisconnect = regexp.MustCompile(`Disconnected from (?:user (\S+) )?(\S+) port (\d+)`)
	reClosed     = regexp.MustCompile(`session closed for user (\S+)`)
)

func classifySSHLine(line string) *Event {
	now := time.Now().UTC().Format(time.RFC3339)
	if m := reAccepted.FindStringSubmatch(line); m != nil {
		return &Event{Type: "SSH_LOGIN", TS: now, User: m[2], IP: m[3], Status: "ok", Meta: "method=" + m[1]}
	}
	if m := reFailed.FindStringSubmatch(line); m != nil {
		return &Event{Type: "SSH_FAILED", TS: now, User: m[2], IP: m[3], Status: "failed", Meta: "method=" + m[1]}
	}
	if m := reClosed.FindStringSubmatch(line); m != nil {
		return &Event{Type: "SSH_LOGOUT", TS: now, User: m[1], Status: "ok"}
	}
	if m := reDisconnect.FindStringSubmatch(line); m != nil {
		user := m[1]
		return &Event{Type: "SSH_LOGOUT", TS: now, User: user, IP: m[2], Status: "ok"}
	}
	return nil
}

// tailSSHJournal follows `journalctl -u <unit> -f` for whichever sshd unit
// name actually exists on this image (ssh.service on Debian/Ubuntu,
// sshd.service on RHEL-family), restarting the subprocess if it dies. Falls
// back to tailing /var/log/auth.log if journalctl isn't usable at all (e.g.
// image without persistent journald), so the feature degrades rather than
// silently doing nothing.
func tailSSHJournal(ctx context.Context, r *ring) {
	unit := detectSSHUnit()
	if unit == "" {
		tailFile(ctx, r, "/var/log/auth.log", classifySSHLine)
		return
	}
	for {
		if ctx.Err() != nil {
			return
		}
		cmd := exec.CommandContext(ctx, "journalctl", "-u", unit, "-f", "-n", "0", "-o", "cat")
		stdout, err := cmd.StdoutPipe()
		if err != nil {
			time.Sleep(5 * time.Second)
			continue
		}
		if err := cmd.Start(); err != nil {
			time.Sleep(5 * time.Second)
			continue
		}
		scanner := bufio.NewScanner(stdout)
		scanner.Buffer(make([]byte, 0, 4096), 64*1024)
		for scanner.Scan() {
			if e := classifySSHLine(scanner.Text()); e != nil {
				r.push(*e)
			}
		}
		_ = cmd.Wait()
		if ctx.Err() != nil {
			return
		}
		time.Sleep(3 * time.Second) // journalctl exited (e.g. journald restart); retry
	}
}

func detectSSHUnit() string {
	for _, unit := range []string{"ssh.service", "sshd.service"} {
		cmd := exec.Command("systemctl", "is-enabled", unit)
		if err := cmd.Run(); err == nil {
			return unit
		}
		cmd2 := exec.Command("systemctl", "is-active", unit)
		if err := cmd2.Run(); err == nil {
			return unit
		}
	}
	// journalctl itself may still work even if the enabled-check above didn't
	// match; try a cheap direct probe as a last resort.
	if out, err := exec.Command("journalctl", "-u", "ssh.service", "-n", "1").CombinedOutput(); err == nil && len(out) > 0 {
		return "ssh.service"
	}
	if out, err := exec.Command("journalctl", "-u", "sshd.service", "-n", "1").CombinedOutput(); err == nil && len(out) > 0 {
		return "sshd.service"
	}
	return ""
}

// tailFile polls a plain log file for new lines (append-only tail -f
// semantics without needing inotify), handling rotation by re-opening when
// the inode shrinks or disappears. classify turns a raw line into an *Event
// (nil to skip).
func tailFile(ctx context.Context, r *ring, path string, classify func(string) *Event) {
	var f *os.File
	var reader *bufio.Reader
	var lastSize int64

	open := func() bool {
		var err error
		f, err = os.Open(path)
		if err != nil {
			return false
		}
		fi, err := f.Stat()
		if err != nil {
			f.Close()
			return false
		}
		lastSize = fi.Size()
		// Start at EOF: we only care about NEW events from process start
		// onward, not the whole historical file.
		if _, err := f.Seek(0, io.SeekEnd); err != nil {
			f.Close()
			return false
		}
		reader = bufio.NewReader(f)
		return true
	}

	ticker := time.NewTicker(750 * time.Millisecond)
	defer ticker.Stop()
	for {
		select {
		case <-ctx.Done():
			if f != nil {
				f.Close()
			}
			return
		case <-ticker.C:
		}
		if f == nil {
			if !open() {
				continue // file doesn't exist (yet, or never will) — keep polling cheaply
			}
		}
		fi, err := os.Stat(path)
		if err != nil {
			f.Close()
			f = nil
			continue
		}
		if fi.Size() < lastSize {
			// Rotated/truncated: reopen from start of new file.
			f.Close()
			f = nil
			if !open() {
				continue
			}
		}
		for {
			line, err := reader.ReadString('\n')
			if line != "" {
				if e := classify(strings.TrimRight(line, "\r\n")); e != nil {
					r.push(*e)
				}
			}
			if err != nil {
				break
			}
		}
		if newFi, err := f.Stat(); err == nil {
			lastSize = newFi.Size()
		}
	}
}

// ---- Web access log detection + parsing ---------------------------------

// combined/common log format: IP - - [ts] "METHOD /path HTTP/x" status size
var reAccessCombined = regexp.MustCompile(`^(\S+) \S+ \S+ \[[^\]]+\] "(\S+) (\S+) \S+" (\d{3}) `)

func classifyAccessLine(line string) *Event {
	m := reAccessCombined.FindStringSubmatch(line)
	if m == nil {
		return nil
	}
	return &Event{
		Type:   "VISITOR",
		TS:     time.Now().UTC().Format(time.RFC3339),
		IP:     m[1],
		Path:   m[3],
		Status: m[4],
		Meta:   "method=" + m[2],
	}
}

// candidateAccessLogs are checked in order; first one that exists wins. This
// intentionally only covers the single-tenant "one web server on this box"
// case (VPS/game server). The centralized HOSTING deployment tails a
// per-vhost log set instead (see watchHostingVhosts).
var candidateAccessLogs = []string{
	"/var/log/nginx/access.log",
	"/var/log/apache2/access.log",
	"/var/log/caddy/access.log",
	"/var/log/httpd/access_log",
}

func detectAccessLog() string {
	for _, p := range candidateAccessLogs {
		if fi, err := os.Stat(p); err == nil && !fi.IsDir() {
			return p
		}
	}
	return ""
}

// ---- Centralized HOSTING mode: many vhost logs on one node ---------------

// hostingLogGlob matches per-account/per-site nginx logs written by
// worker/hosting.ts (see NOTE in commit message: today's shared-hosting
// vhosts don't set a per-account access_log directive, so this glob also
// covers the platform-wide default log as a fallback "site" named "_default").
const hostingLogDir = "/var/log/nginx"

func watchHostingVhosts(ctx context.Context, r *ring) {
	seen := map[string]bool{}
	var wg sync.WaitGroup
	scan := func() {
		entries, err := os.ReadDir(hostingLogDir)
		if err != nil {
			return
		}
		for _, e := range entries {
			if e.IsDir() || !strings.HasSuffix(e.Name(), "access.log") {
				continue
			}
			p := filepath.Join(hostingLogDir, e.Name())
			if seen[p] {
				continue
			}
			seen[p] = true
			site := strings.TrimSuffix(e.Name(), ".access.log")
			wg.Add(1)
			go func(path, site string) {
				defer wg.Done()
				tailFile(ctx, r, path, func(line string) *Event {
					e := classifyAccessLine(line)
					if e != nil {
						e.Site = site
					}
					return e
				})
			}(p, site)
		}
	}
	scan()
	ticker := time.NewTicker(30 * time.Second) // pick up newly provisioned sites
	defer ticker.Stop()
	for {
		select {
		case <-ctx.Done():
			wg.Wait()
			return
		case <-ticker.C:
			scan()
		}
	}
}

// ---- Centralized MAIL mode: Dovecot/Postfix auth log ---------------------

var reMailAuth = regexp.MustCompile(`(?:dovecot|postfix/smtpd).*?(?:Login|login): user=<([^>]*)>.*?rip=([0-9a-fA-F:.]+)|(?:dovecot).*?auth failed.*?user=<([^>]*)>.*?rip=([0-9a-fA-F:.]+)`)

func classifyMailLine(line string) *Event {
	lower := strings.ToLower(line)
	if !strings.Contains(lower, "dovecot") && !strings.Contains(lower, "postfix") {
		return nil
	}
	m := reMailAuth.FindStringSubmatch(line)
	if m == nil {
		return nil
	}
	now := time.Now().UTC().Format(time.RFC3339)
	if m[1] != "" {
		return &Event{Type: "MAIL_AUTH", TS: now, User: m[1], IP: m[2], Status: "ok"}
	}
	return &Event{Type: "MAIL_AUTH", TS: now, User: m[3], IP: m[4], Status: "failed"}
}

// ---- main -----------------------------------------------------------------

func main() {
	cfg, err := loadConfig()
	if err != nil {
		log.Fatalf("nxeon-shipper: %v", err)
	}

	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	r := newRing(maxBufferedEvts)
	go sender(ctx, cfg, r)

	switch cfg.NodeKind {
	case "HOSTING":
		go watchHostingVhosts(ctx, r)
	case "MAIL":
		// Mailcow's postfix/dovecot logs land in the mail node's own journal
		// under docker's forwarding; mailcow-compose ships a "postfix-mailcow"
		// / "dovecot-mailcow" container. We tail the host-side syslog file
		// mailcow's vmail-stats/rsyslog forwards to, which is the simplest
		// integration that doesn't require joining the docker network.
		go tailFile(ctx, r, "/var/log/mail.log", classifyMailLine)
	default: // VPS, GAME
		go tailSSHJournal(ctx, r)
		if p := detectAccessLog(); p != "" {
			go tailFile(ctx, r, p, classifyAccessLine)
		}
		// else: no web server on this box — skip gracefully, per spec.
	}

	// Idle CPU/RAM stays negligible: everything above is either blocked on a
	// subprocess pipe read, a 750ms/30s ticker, or the 3s batch ticker — no
	// busy loops anywhere.
	sig := make(chan os.Signal, 1)
	notifySignals(sig)
	<-sig
	cancel()
	time.Sleep(200 * time.Millisecond) // let sender flush its last drain cycle's HTTP call
}

func mustAtoi(s string) int {
	n, _ := strconv.Atoi(s)
	return n
}

