/**
 * Per-server / per-node bearer tokens for the nxeon-shipper live-telemetry
 * agent (see agent/nxeon-shipper). Unlike lib/terminal-token.ts (a 60s JWE
 * minted per browser session), a shipper token is a PERSISTENT machine
 * credential baked into cloud-init / a node's shipper config at provision
 * time and used indefinitely from then on — so it follows the same
 * hash-at-rest convention as password-reset tokens and the deploy-hook
 * secrets in lib/actions-account.ts, NOT the ephemeral-JWE convention:
 *
 *   - mint(): random 32-byte token, return the raw value ONCE, store only
 *     its SHA-256 hash (`Server.telemetryTokenHash` / `HostingNode.telemetryTokenHash`).
 *   - lookupByToken(): hash the presented token and look the owner up by the
 *     unique hash column — the same shape as PasswordResetToken lookups.
 *
 * There's no rotation UI yet (Phase 2): re-provisioning a server mints a
 * fresh token and overwrites the old hash, which is all we need since a
 * leaked shipper token only grants "post low-value connection-event rows
 * for this one server," not read/write access to anything else.
 */
import { randomBytes, createHash } from "node:crypto";
import { db } from "./db";

export function mintTelemetryToken(): { token: string; hash: string } {
  const token = randomBytes(32).toString("base64url");
  const hash = createHash("sha256").update(token).digest("hex");
  return { token, hash };
}

export function hashTelemetryToken(token: string): string {
  return createHash("sha256").update(token).digest("hex");
}

/**
 * Mint a fresh telemetry token for a server, persist its hash, and return
 * the raw token to embed in that server's cloud-init config. Call this once
 * per (re)provision, right before buildCloudInit() so the config file the
 * agent boots with matches the hash we just stored.
 */
export async function mintServerTelemetryToken(serverId: string): Promise<string> {
  const { token, hash } = mintTelemetryToken();
  await db.server.update({ where: { id: serverId }, data: { telemetryTokenHash: hash } });
  return token;
}

export async function mintHostingNodeTelemetryToken(nodeId: string): Promise<string> {
  const { token, hash } = mintTelemetryToken();
  await db.hostingNode.update({ where: { id: nodeId }, data: { telemetryTokenHash: hash } });
  return token;
}

export type TelemetryPrincipal =
  | { kind: "VPS" | "GAME"; serverId: string }
  | { kind: "HOSTING"; nodeId: string }
  | { kind: "MAIL" };

/**
 * Resolve a presented bearer token to the server/node it belongs to. Checked
 * in order: Server (VPS/GAME — nodeKind carried by the shipper's own config,
 * not re-derived here since a game server and a VPS look identical at this
 * layer), then HostingNode, then the single static MAIL_TELEMETRY_TOKEN env
 * secret (the mail box has no Prisma row to hang a hash off today — see
 * commit message for why a static shared secret is an acceptable stopgap for
 * one fixed, admin-controlled centralized node).
 */
export async function resolveTelemetryPrincipal(token: string, claimedNodeKind: string): Promise<TelemetryPrincipal | null> {
  if (!token) return null;
  const hash = hashTelemetryToken(token);

  if (claimedNodeKind === "MAIL") {
    const secret = process.env.MAIL_TELEMETRY_TOKEN;
    if (secret && hash === hashTelemetryToken(secret)) return { kind: "MAIL" };
    return null;
  }

  if (claimedNodeKind === "HOSTING") {
    const node = await db.hostingNode.findUnique({ where: { telemetryTokenHash: hash }, select: { id: true } });
    return node ? { kind: "HOSTING", nodeId: node.id } : null;
  }

  const server = await db.server.findUnique({
    where: { telemetryTokenHash: hash },
    select: { id: true, gameVariant: true },
  });
  if (!server) return null;
  return { kind: server.gameVariant ? "GAME" : "VPS", serverId: server.id };
}

