/**
 * Live-telemetry ingestion + read-back for the nxeon-shipper agent feature.
 *
 * WHAT THIS IS: a short rolling window (TELEMETRY_RETENTION_HOURS) of raw
 * connection/auth events shipped by nxeon-shipper — SSH logins/logouts/failed
 * attempts, visitor HTTP hits, and mail auth attempts — fanned into the same
 * /admin/monitor page the existing Live Ops feed (lib/monitor-feed.ts) drives.
 *
 * ARCHITECTURE CALL (documented per the task's "make the reasonable call"
 * instruction): this is DB-backed (a `TelemetryEvent` row per event), read by
 * the existing 8s poll in LiveMonitorTerminal, NOT a new SSE/WebSocket
 * channel. Reasons:
 *   1. Single-node deployment (see docs/DOCUMENTATION.md) — there is exactly
 *      one Next.js process and one worker process; a push channel would only
 *      be saving the latency of one indexed, limit-50 query every 8s, which
 *      is not meaningfully "not live" for an ops console (SSH events show up
 *      within one poll tick, i.e. worst-case ~8s, typically 2-5s given the
 *      shipper's own 3s batch interval).
 *   2. The existing monitor page is ALREADY a poll loop end to end (route +
 *      component); adding a second transport (SSE) alongside it for only
 *      SOME event types would fragment the one console into two update
 *      cadences for no operator-visible benefit, and every other admin
 *      surface in this codebase (Jobs, HostingTask, node stats) is polled
 *      the same way.
 *   3. Postgres growth is bounded by retention (below) + the worker sweep
 *      (worker/telemetry.ts telemetrySweep), so "DB as ring buffer" carries
 *      none of the unbounded-growth risk that would make this a bad idea.
 * If a future phase needs sub-second delivery (e.g. a live "who's SSH'd in
 * right now" indicator), promote just that slice to SSE — terminal-server's
 * `ws` dependency is already in the tree as prior art for a push channel.
 */
import { db } from "./db";
import { resolveTelemetryPrincipal } from "./telemetry-token";

export const TELEMETRY_RETENTION_HOURS = 48;
/** Hard cap on events accepted per batch POST — matches the shipper's own
 *  batchMaxEvents (50) with headroom, so a misbehaving/compromised agent
 *  can't smuggle an oversized payload through one request. */
const MAX_EVENTS_PER_BATCH = 200;
const VALID_TYPES = new Set(["SSH_LOGIN", "SSH_LOGOUT", "SSH_FAILED", "VISITOR", "MAIL_AUTH"]);
const VALID_NODE_KINDS = new Set(["VPS", "GAME", "HOSTING", "MAIL"]);

export type EventIn = {
  type: string;
  ts: string;
  ip?: string;
  user?: string;
  path?: string;
  status?: string;
  meta?: string;
  site?: string;
};

export type BatchIn = {
  server_id?: string;
  node_kind?: string;
  label?: string;
  events?: EventIn[];
};

function clip(s: string | undefined | null, max: number): string | undefined {
  if (!s) return undefined;
  return s.length > max ? s.slice(0, max) : s;
}

/**
 * Validate the bearer token against Server/HostingNode/mail-secret, validate
 * + clamp the batch shape, and insert. Returns the count actually stored (0
 * if the token was invalid or the batch was empty/malformed — callers should
 * still answer 401 for a bad token, this function only owns the DB write).
 */
export async function ingestTelemetryBatch(
  token: string,
  body: BatchIn
): Promise<{ ok: true; stored: number } | { ok: false; reason: string }> {
  const nodeKind = body.node_kind && VALID_NODE_KINDS.has(body.node_kind) ? body.node_kind : "VPS";
  const principal = await resolveTelemetryPrincipal(token, nodeKind);
  if (!principal) return { ok: false, reason: "invalid token" };

  const events = Array.isArray(body.events) ? body.events.slice(0, MAX_EVENTS_PER_BATCH) : [];
  if (events.length === 0) return { ok: true, stored: 0 };

  const label = clip(body.label, 200) ?? null;
  const rows = events
    .filter((e) => e && typeof e.type === "string" && VALID_TYPES.has(e.type))
    .map((e) => {
      let ts = new Date(e.ts);
      if (Number.isNaN(ts.getTime())) ts = new Date();
      return {
        serverId: principal.kind === "VPS" || principal.kind === "GAME" ? principal.serverId : null,
        nodeId: principal.kind === "HOSTING" ? principal.nodeId : principal.kind === "MAIL" ? "mail" : null,
        nodeKind: principal.kind,
        type: e.type,
        ts,
        ip: clip(e.ip, 64) ?? null,
        user: clip(e.user, 128) ?? null,
        path: clip(e.path, 512) ?? null,
        site: clip(e.site, 200) ?? null,
        status: clip(e.status, 32) ?? null,
        meta: clip(e.meta, 256) ?? null,
        label,
      };
    });
  if (rows.length === 0) return { ok: true, stored: 0 };

  await db.telemetryEvent.createMany({ data: rows });
  return { ok: true, stored: rows.length };
}

export type TelemetryEventView = {
  id: string;
  serverId: string | null;
  nodeId: string | null;
  nodeKind: string;
  type: string;
  ts: string;
  ip: string | null;
  user: string | null;
  path: string | null;
  site: string | null;
  status: string | null;
  meta: string | null;
  label: string | null;
};

/**
 * Recent events for the admin monitor feed. Capped at `limit` (the monitor
 * UI only ever shows a scrolling tail, same as the existing Job/HostingTask
 * action log), ordered newest-first.
 */
export async function getRecentTelemetry(limit = 80): Promise<TelemetryEventView[]> {
  const rows = await db.telemetryEvent.findMany({
    orderBy: { createdAt: "desc" },
    take: limit,
  });
  return rows.map((r) => ({
    id: r.id,
    serverId: r.serverId,
    nodeId: r.nodeId,
    nodeKind: r.nodeKind,
    type: r.type,
    ts: r.ts.toISOString(),
    ip: r.ip,
    user: r.user,
    path: r.path,
    site: r.site,
    status: r.status,
    meta: r.meta,
    label: r.label,
  }));
}

/**
 * Prune rows past the retention window. Called first (before anything that
 * could throw) by worker/telemetry.ts's sweep, same "prune, then act" order
 * as worker/monitor.ts sampleServerDisks — a prune failure must never block
 * the rest of the sweep, and the rest of the sweep must never leave stale
 * rows to expire only when a LATER sweep happens to succeed.
 */
export async function pruneTelemetry(): Promise<number> {
  const cutoff = new Date(Date.now() - TELEMETRY_RETENTION_HOURS * 60 * 60_000);
  const { count } = await db.telemetryEvent.deleteMany({ where: { createdAt: { lt: cutoff } } });
  return count;
}

