import { NextRequest, NextResponse } from "next/server";
import { NO_STORE_HEADERS } from "@/app/api/_lib/no-store";
import { checkRateLimit } from "@/lib/rate-limit";
import { ingestTelemetryBatch, type BatchIn } from "@/lib/telemetry";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

/**
 * POST /api/telemetry/ingest — receives a batched-events payload from the
 * nxeon-shipper agent (see agent/nxeon-shipper/main.go `sender()`), running
 * either per-server on a VPS/game box or once centrally on a shared-hosting
 * or mail node.
 *
 * AUTH: `Authorization: Bearer <token>` — a persistent, hash-at-rest token
 * minted at provision time (lib/telemetry-token.ts), NOT the session-cookie
 * auth every other API route in this app uses. This endpoint is reachable
 * from customer VMs on the public internet, not just the admin's browser.
 *
 * This intentionally does the least amount of work possible per request:
 * validate the token, clamp + insert the batch, return. No fan-out, no
 * websocket push here — the admin monitor page reads back via its existing
 * poll (see lib/telemetry.ts header comment for why that's the right call
 * on a single-node deployment).
 */
export async function POST(req: NextRequest) {
  const auth = req.headers.get("authorization") ?? "";
  const token = auth.startsWith("Bearer ") ? auth.slice(7).trim() : "";
  if (!token) {
    return NextResponse.json({ error: "unauthorized" }, { status: 401, headers: NO_STORE_HEADERS });
  }

  // Throttle per-token rather than per-IP: a shipper on a NATted VM shares an
  // IP with the platform's own NAT gateway, but always presents its own
  // token, so this is the correct dedup key. Generous ceiling — a legitimate
  // shipper posts ~1 batch/3s; this allows bursts (e.g. reconnect after an
  // outage flushing several catch-up batches) without false-positiving.
  const rl = checkRateLimit(`telemetry:ingest:${token}`, { max: 40, windowMs: 60_000 });
  if (!rl.ok) {
    return NextResponse.json({ error: "rate limited" }, { status: 429, headers: NO_STORE_HEADERS });
  }

  let body: BatchIn;
  try {
    body = await req.json();
  } catch {
    return NextResponse.json({ error: "invalid json" }, { status: 400, headers: NO_STORE_HEADERS });
  }

  try {
    const result = await ingestTelemetryBatch(token, body);
    if (!result.ok) {
      return NextResponse.json({ error: result.reason }, { status: 401, headers: NO_STORE_HEADERS });
    }
    return NextResponse.json({ ok: true, stored: result.stored }, { headers: NO_STORE_HEADERS });
  } catch (e) {
    console.error("[telemetry/ingest] route error", e);
    return NextResponse.json({ error: "ingest failed" }, { status: 500, headers: NO_STORE_HEADERS });
  }
}

