/**
 * Worker-side upkeep for the live-telemetry feature (lib/telemetry.ts /
 * agent/nxeon-shipper). The ingestion route (app/api/telemetry/ingest) does
 * all the writing; this sweep only prunes — same "prune first, so a later
 * failure never leaves the table growing unbounded" shape as
 * worker/monitor.ts sampleServerDisks(), scheduled on the same 10-minute
 * `lastMonitorSweep` cadence in worker/index.ts (telemetry events don't need
 * a tighter prune cadence than disk samples do).
 */
import { pruneTelemetry } from "../lib/telemetry";

export async function telemetryPruneSweep(): Promise<void> {
  try {
    const pruned = await pruneTelemetry();
    if (pruned > 0) console.log(`[telemetry] pruned ${pruned} events past retention`);
  } catch (e) {
    console.error("[telemetry] prune error", e);
  }
}

