// ---- Live-telemetry shipper deploy sweep (admin-triggered) -----------------

const TELEMETRY_DEPLOY_LOG_MAX = 4000;

/**
 * Deploy the CENTRALIZED nxeon-shipper to one admin-QUEUED HostingNode: mint
 * a node-level token (lib/telemetry-token.ts — one shipper covers every
 * customer account on the box, so this is one token per node, not one per
 * account), then curl the static binary + systemd unit from our own APP_URL
 * (same trick cloud-init uses — see worker/index.ts shipperInstallScript)
 * and enable it. The agent then self-discovers every vhost access log under
 * /var/log/nginx on its own 30s rescan (agent/nxeon-shipper watchHostingVhosts)
 * — so newly added customer sites need NO further action here.
 *
 * Same QUEUED/RUNNING/DONE/FAILED shape as hostingNodeHardenSweep, and same
 * guarantee: this NEVER auto-queues a node. It only acts on a node an admin
 * explicitly queued via the admin Nodes page, so shipping this code cannot by
 * itself touch a node that's already live serving customers.
 */
export async function hostingNodeTelemetryDeploySweep(): Promise<void> {
  if (SANDBOX) {
    const queued = await db.hostingNode.findMany({ where: { telemetryDeployStatus: "QUEUED" }, select: { id: true } });
    for (const n of queued) {
      await db.hostingNode
        .update({
          where: { id: n.id },
          data: { telemetryDeployStatus: "DONE", telemetryDeployedAt: new Date(), telemetryDeployLog: "[sandbox] shipper deploy simulated" },
        })
        .catch(() => undefined);
    }
    return;
  }

  const node = await db.hostingNode.findFirst({ where: { telemetryDeployStatus: "QUEUED" }, orderBy: { createdAt: "asc" } });
  if (!node) return;
  await db.hostingNode.update({ where: { id: node.id }, data: { telemetryDeployStatus: "RUNNING" } });

  try {
    const { mintHostingNodeTelemetryToken } = await import("../lib/telemetry-token");
    const token = await mintHostingNodeTelemetryToken(node.id);
    const appUrl = process.env.APP_URL ?? "https://nxeon.cloud";
    const config = JSON.stringify({ server_id: node.id, token, ingest_url: `${appUrl}/api/telemetry/ingest`, node_kind: "HOSTING", label: node.name });
    const b64Config = Buffer.from(config, "utf8").toString("base64");
    const script = [
      "set -o pipefail",
      "mkdir -p /etc/nxeon",
      `printf %s '${b64Config}' | base64 -d > /etc/nxeon/shipper.json`,
      "chmod 600 /etc/nxeon/shipper.json",
      `curl -fsSL "${appUrl}/dl/nxeon-shipper-linux-amd64" -o /usr/local/bin/nxeon-shipper.tmp && chmod +x /usr/local/bin/nxeon-shipper.tmp && mv /usr/local/bin/nxeon-shipper.tmp /usr/local/bin/nxeon-shipper`,
      `curl -fsSL "${appUrl}/dl/nxeon-shipper.service" -o /etc/systemd/system/nxeon-shipper.service`,
      "systemctl daemon-reload && systemctl enable --now nxeon-shipper",
      "systemctl is-active nxeon-shipper",
    ].join(" && ");

    const conn = await connectNode(node);
    try {
      const { code, out } = await exec(conn, script, HARDEN_TIMEOUT_MS);
      await db.hostingNode.update({
        where: { id: node.id },
        data: {
          telemetryDeployStatus: code === 0 ? "DONE" : "FAILED",
          telemetryDeployedAt: new Date(),
          telemetryDeployLog: out.slice(-TELEMETRY_DEPLOY_LOG_MAX),
        },
      });
    } finally {
      try { conn.end(); } catch { /* */ }
    }
  } catch (e) {
    await db.hostingNode
      .update({
        where: { id: node.id },
        data: {
          telemetryDeployStatus: "FAILED",
          telemetryDeployedAt: new Date(),
          telemetryDeployLog: (e instanceof Error ? e.message : String(e)).slice(-TELEMETRY_DEPLOY_LOG_MAX),
        },
      })
      .catch(() => undefined);
  }
}

