 * not touch any node that's already live serving customers until asked to).
 */
export async function adminDeployHostingNodeTelemetry(id: string): Promise<{ ok?: boolean; error?: string }> {
  await requireArea("fleet");
  const n = await db.hostingNode.findUnique({ where: { id }, select: { telemetryDeployStatus: true } });
  if (!n) return { error: "Node not found." };
  if (n.telemetryDeployStatus === "QUEUED" || n.telemetryDeployStatus === "RUNNING") {
    return { error: "Telemetry shipper deploy is already in progress for this node." };
  }
  await db.hostingNode.update({ where: { id }, data: { telemetryDeployStatus: "QUEUED", telemetryDeployLog: null } });
  revalidatePath("/admin/hosting");
  return { ok: true };
}

