  // empty (or OVH isn't configured) it transparently falls back to shared NAT.
  let dedicated: { address: string; virtualMac: string; gateway: string } | null = null;
  const { getSettingBool: _settingBool } = await import("../lib/settings");
  const wantDedicated = server.wantsDedicatedIp || (await _settingBool("dedicated_ip_default", true));
