import { test } from "node:test";
import assert from "node:assert/strict";
import { buildTelemetryRows, TELEMETRY_RETENTION_HOURS, clip } from "../lib/telemetry.ts";
import { mintTelemetryToken, hashTelemetryToken } from "../lib/telemetry-token.ts";

/* ---- token minting (pure crypto, no DB) ---- */

test("mintTelemetryToken returns a token whose hash matches hashTelemetryToken", () => {
  const { token, hash } = mintTelemetryToken();
  assert.equal(hash, hashTelemetryToken(token));
});

test("mintTelemetryToken never repeats (32 random bytes)", () => {
  const a = mintTelemetryToken();
  const b = mintTelemetryToken();
  assert.notEqual(a.token, b.token);
  assert.notEqual(a.hash, b.hash);
});

test("hashTelemetryToken is deterministic", () => {
  assert.equal(hashTelemetryToken("same-input"), hashTelemetryToken("same-input"));
});

/* ---- retention sanity ---- */

test("TELEMETRY_RETENTION_HOURS is a short rolling window (24-48h per spec)", () => {
  assert.ok(TELEMETRY_RETENTION_HOURS >= 24 && TELEMETRY_RETENTION_HOURS <= 48);
});

/* ---- clip() ---- */

test("clip truncates over-length strings and passes short ones through", () => {
  assert.equal(clip("hello", 10), "hello");
  assert.equal(clip("hello world", 5), "hello");
  assert.equal(clip(undefined, 5), undefined);
  assert.equal(clip(null, 5), undefined);
  assert.equal(clip("", 5), undefined);
});

/* ---- buildTelemetryRows: the batch → row transform the ingest route relies on ---- */

test("buildTelemetryRows maps a VPS/GAME batch to rows carrying serverId, not nodeId", () => {
  const rows = buildTelemetryRows(
    { kind: "VPS", serverId: "srv_1" },
    { events: [{ type: "SSH_LOGIN", ts: new Date().toISOString(), user: "root", ip: "1.2.3.4" }] }
  );
  assert.equal(rows.length, 1);
  assert.equal(rows[0].serverId, "srv_1");
  assert.equal(rows[0].nodeId, null);
  assert.equal(rows[0].nodeKind, "VPS");
  assert.equal(rows[0].user, "root");
});

test("buildTelemetryRows maps a HOSTING batch to rows carrying nodeId, not serverId", () => {
  const rows = buildTelemetryRows(
    { kind: "HOSTING", nodeId: "node_1" },
    { events: [{ type: "VISITOR", ts: new Date().toISOString(), ip: "5.6.7.8", path: "/", site: "acme.com" }] }
  );
  assert.equal(rows[0].serverId, null);
  assert.equal(rows[0].nodeId, "node_1");
  assert.equal(rows[0].site, "acme.com");
});

test("buildTelemetryRows maps a MAIL batch to the fixed 'mail' nodeId", () => {
  const rows = buildTelemetryRows(
    { kind: "MAIL" },
    { events: [{ type: "MAIL_AUTH", ts: new Date().toISOString(), user: "billing@nxeon.cloud" }] }
  );
  assert.equal(rows[0].nodeId, "mail");
  assert.equal(rows[0].nodeKind, "MAIL");
});

test("buildTelemetryRows drops events with an unknown/missing type", () => {
  const rows = buildTelemetryRows(
    { kind: "VPS", serverId: "srv_1" },
    {
      events: [
        { type: "NOT_A_REAL_TYPE", ts: new Date().toISOString() },
        { type: "SSH_LOGIN", ts: new Date().toISOString() },
        // @ts-expect-error deliberately malformed input, exactly what a buggy/hostile shipper could send
        { ts: new Date().toISOString() },
      ] as any,
    }
  );
  assert.equal(rows.length, 1);
  assert.equal(rows[0].type, "SSH_LOGIN");
});

test("buildTelemetryRows clamps a batch far larger than the shipper's own cap", () => {
  const events = Array.from({ length: 500 }, () => ({ type: "SSH_LOGIN", ts: new Date().toISOString() }));
  const rows = buildTelemetryRows({ kind: "VPS", serverId: "srv_1" }, { events });
  assert.ok(rows.length <= 200, `expected <=200 rows, got ${rows.length}`);
});

test("buildTelemetryRows falls back to now() for an unparseable timestamp rather than throwing", () => {
  const rows = buildTelemetryRows(
    { kind: "VPS", serverId: "srv_1" },
    { events: [{ type: "SSH_LOGIN", ts: "not-a-date" }] }
  );
  assert.equal(rows.length, 1);
  assert.ok(!Number.isNaN(rows[0].ts.getTime()));
});

test("buildTelemetryRows clips oversized free-form fields (defense against a hostile/buggy shipper)", () => {
  const rows = buildTelemetryRows(
    { kind: "VPS", serverId: "srv_1" },
    { events: [{ type: "VISITOR", ts: new Date().toISOString(), path: "/" + "a".repeat(2000) }] }
  );
  assert.ok(rows[0].path && rows[0].path.length <= 512);
});

