// live-telemetry feature. Runs against a throwaway local Postgres DB
// (nxeon_livetel_e2e) created solely for this test — NOT staging, NOT
// production. Creates the minimal User/Plan/OsTemplate/Server fixture rows
// needed for the ingest route to resolve a telemetry token, mints a real
// token via the actual lib/telemetry-token.ts code, and prints the cloud-init
// snippet (built from the actual worker/index.ts shipper-install logic) to
// hand to `qm` directly. Delete this file when done.
import { db } from "../lib/db";
import { mintServerTelemetryToken } from "../lib/telemetry-token";

async function main() {
  const user = await db.user.upsert({
    where: { email: "e2e-test@nxeon.local" },
    update: {},
    create: { email: "e2e-test@nxeon.local", name: "E2E Test", role: "ADMIN", passwordHash: "x" },
  });
  const plan =
    (await db.plan.findFirst()) ??
    (await db.plan.create({
      data: { name: "E2E-Nano", priceCents: 100, cpuCores: 1, ramMB: 1024, diskGB: 15, bandwidthTB: 1, storageTier: "nvme" },
    }));
  const os =
    (await db.osTemplate.findFirst()) ??
    (await db.osTemplate.create({ data: { name: "Ubuntu 24.04 LTS", family: "linux", category: "PLAIN_OS" } }));

  const server = await db.server.create({
    data: {
