      status: "RUNNING",
      userId: user.id,
      planId: plan.id,
      osTemplateId: os.id,
    },
  });

  const token = await mintServerTelemetryToken(server.id);
  console.log("SERVER_ID=" + server.id);
  console.log("TOKEN=" + token);
}

main()
  .catch((e) => {
    console.error("ERROR", e);
    process.exit(1);
  })
